<script setup lang="ts">
import { computed,onMounted } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { discoverApi,type Tracker } from '@/api/discover'
import RequestState from './RequestState.vue'
import DiscoverGlyph from './DiscoverGlyph.vue'
import { useCommunityResource } from './resource'
import { displayDate,officialSource } from './contract'
const route=useRoute(),router=useRouter()
const tab=computed(()=>route.query.track==='promos'?'promos':'launches')
const {data,loading,error,load}=useCommunityResource(discoverApi.tracker)
onMounted(load)
function setTab(track:string){void router.replace({query:{...route.query,track}})}
const quota=computed(()=>data.value?.quota as (NonNullable<Tracker['quota']>&{recent_intervals?:number[]})|undefined)
const progress=computed(()=>typeof quota.value?.progress_pct==='number'&&Number.isFinite(quota.value.progress_pct)&&quota.value.progress_pct>=0&&quota.value.progress_pct<=100?quota.value.progress_pct:null)
function dateTime(raw:string){const date=new Date(raw);return Number.isNaN(date.getTime())?raw:date.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})}
</script>
<template><div class="tracker-feed"><nav class="track-filter" aria-label="追踪类型"><button v-for="item in [{key:'launches',label:'发布记录',icon:'bolt'},{key:'promos',label:'优惠与试用',icon:'tag'}]" :key="item.key" :class="{on:tab===item.key}" :aria-pressed="tab===item.key" @click="setTab(item.key)"><DiscoverGlyph :name="item.icon" :size="16"/>{{ item.label }}</button></nav><RequestState :loading="loading" :error="error" @retry="load"/><template v-if="data">
<section v-if="quota" class="track-card quota-card"><header><h2><DiscoverGlyph name="refresh" :size="18"/>Codex 重置观察</h2><span v-if="quota.sample" class="sample">示例</span></header><div class="quota-body"><div v-if="progress!=null" class="progress-ring"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="42" class="ring-track"/><circle cx="50" cy="50" r="42" class="ring-value" pathLength="100" :stroke-dasharray="`${progress} 100`"/></svg><span><strong>{{ progress }}%</strong><small>本轮已过</small></span></div><div class="quota-time"><span>预计下次重置</span><strong>{{ quota.next_reset_at?dateTime(quota.next_reset_at):'暂无时间' }}</strong><p v-if="quota.published_at">{{ displayDate(quota.published_at) }} 更新</p></div></div><p class="fine-print">站方记录的重置观察，不代表个人剩余额度。</p></section>
<section v-if="tab==='launches'" class="track-card"><header><h2><DiscoverGlyph name="bolt" :size="18"/>发布记录</h2><span class="count">{{ data.launches.length }} 条</span></header><div v-if="data.launches.length" class="timeline"><article v-for="launch in data.launches" :key="launch.key" class="launch"><span class="timeline-dot" aria-hidden="true"/><div class="launch-top"><time>{{ displayDate(launch.published_at)||'日期未提供' }}</time><span v-if="launch.sample" class="sample">示例</span></div><h3>{{ launch.title }}</h3><div v-if="launch.tags?.length" class="tags"><span v-for="tag in launch.tags" :key="tag">{{ tag }}</span></div><details v-if="launch.summary"><summary>发布说明<DiscoverGlyph name="down" :size="14"/></summary><p>{{ launch.summary }}</p></details><a v-if="officialSource(launch.source_url)" :href="officialSource(launch.source_url)" target="_blank" rel="noopener noreferrer" class="official-link">官方原文<DiscoverGlyph name="external" :size="13"/></a></article></div><RequestState :empty="!data.launches.length" message="暂无已核实的发布记录。"/></section>
<template v-else><div class="promo-heading"><h2><DiscoverGlyph name="clock" :size="18"/>优惠与试用</h2><span>{{ data.promos.length }} 条</span></div><div class="promo-grid"><article v-for="promo in data.promos" :key="promo.key" class="track-card promo"><header><span class="promo-icon"><DiscoverGlyph name="tag" :size="20"/></span><span v-if="promo.ends_at&&promo.days_left!=null" class="days">剩 {{ promo.days_left }} 天</span><span v-if="promo.sample" class="sample">示例</span></header><h3>{{ promo.text }}</h3><p v-if="promo.eligibility" class="eligibility">{{ promo.eligibility }}</p><p class="deadline"><DiscoverGlyph name="clock" :size="14"/>{{ promo.ends_at?`截止 ${displayDate(promo.ends_at)}`:'长期提供，以官方条件为准' }}</p><a v-if="officialSource(promo.source_url)" :href="officialSource(promo.source_url)" target="_blank" rel="noopener noreferrer" class="official-link">官方条件与申请入口<DiscoverGlyph name="external" :size="13"/></a></article></div><RequestState :empty="!data.promos.length" message="暂无已核实的进行中优惠。"/></template><p v-if="data.sample" class="fine-print sample-note"><DiscoverGlyph name="info" :size="14"/>带「示例」字样的内容为示例数据。</p>
</template></div></template>
<style scoped>
.tracker-feed{display:grid;gap:8px;padding-top:8px;min-width:0}.track-filter{display:flex;gap:8px;padding:0 0 4px}.track-filter button{display:flex;align-items:center;gap:6px;min-height:44px;border:0;padding:8px 14px;border-radius:10px;background:var(--surface);color:var(--ink-3);font-size:14px;cursor:pointer}.track-filter button.on{background:color-mix(in srgb,var(--brand) 8%,var(--surface));color:var(--brand);font-weight:500}.track-card{padding:16px;background:var(--surface);border-radius:16px;min-width:0}header{display:flex;align-items:center;justify-content:space-between;gap:8px}h2{display:flex;align-items:center;gap:6px;font-size:16px;margin:0;font-weight:600}.sample{color:var(--brand);font-size:12px;white-space:nowrap}.count{font-size:12px;color:var(--ink-3)}.timeline{padding:16px 0 0 8px}.launch{position:relative;border-left:1px solid var(--line);padding:0 0 18px 20px;min-width:0}.launch:last-child{padding-bottom:0;border-left-color:transparent}.timeline-dot{position:absolute;left:-4px;top:5px;width:7px;height:7px;border-radius:50%;background:var(--surface-2);box-shadow:0 0 0 3px var(--surface)}.launch:first-child .timeline-dot{background:var(--brand)}.launch-top{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-3)}h3{margin:6px 0 0;font-size:15px;font-weight:600;line-height:1.65;overflow-wrap:anywhere}.tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.tags span{font-size:12px;color:var(--ink-3);padding:2px 6px;border-radius:4px;background:var(--surface-2)}details{margin-top:4px;font-size:12px;color:var(--ink-3)}summary{display:inline-flex;align-items:center;gap:4px;list-style:none;min-height:36px;cursor:pointer}summary::-webkit-details-marker{display:none}details[open] summary svg{transform:rotate(180deg)}details p{margin:0 0 8px;white-space:pre-line;line-height:1.8;color:var(--ink-2);font-size:14px}.official-link{display:inline-flex;align-items:center;gap:5px;min-height:44px;color:var(--brand);font-size:12px}.promo-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 4px}.promo-heading>span{font-size:12px;color:var(--ink-3)}.promo-grid{display:grid;gap:8px;min-width:0}.promo header{justify-content:flex-start}.promo-icon{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:var(--surface-2);color:var(--ink-2)}.days{margin-left:auto;color:var(--ink-3);font-size:12px;background:var(--surface-2);padding:4px 8px;border-radius:6px}.promo h3{margin-top:12px}.eligibility{font-size:14px;line-height:1.8;color:var(--ink-2);margin:8px 0}.deadline{display:flex;align-items:center;gap:5px;font-size:12px;color:var(--ink-3);margin:12px 0 0}.fine-print{font-size:12px;line-height:1.7;color:var(--ink-3);margin:8px 0 0}.sample-note{display:flex;align-items:center;gap:6px;padding:4px;margin:0}.quota-body{display:flex;align-items:center;gap:20px;padding:16px 0 4px}.progress-ring{width:88px;height:88px;position:relative;flex:none}.progress-ring svg{width:100%;height:100%;transform:rotate(-90deg)}.progress-ring circle{fill:none;stroke-width:7}.ring-track{stroke:var(--surface-2)}.ring-value{stroke:var(--brand);stroke-linecap:round}.progress-ring>span{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px}.progress-ring strong{font-size:20px}.progress-ring small{font-size:12px;color:var(--ink-3)}.quota-time{display:flex;flex-direction:column;gap:8px;min-width:0}.quota-time>span,.quota-time p{font-size:12px;color:var(--ink-3);margin:0}.quota-time strong{font-size:16px;line-height:1.5}@media(min-width:768px){.tracker-feed{gap:12px}.track-card{padding:20px}.promo-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.launch{padding-bottom:24px}.quota-card{max-width:100%}.quota-body{gap:24px}}
</style>
